data[1020001] = { id = 1020001,  language = "受到魔法影响而变异的沟鼠。牙齿非常锋利，虽然看起来不堪一击，但被咬中可不是闹着玩的。"}
data[1020002] = { id = 1020002,  language = "肥厚的洞穴水蛭看起来比普通的水蛭大了不少，也更具攻击性。"}
data[1020003] = { id = 1020003,  language = "也被称为业力之火，焚尽一些污秽之物是它存在的唯一意义。"}
data[1020004] = { id = 1020004,  language = "生活在火山内部的一种蝙蝠，炙热的翅膀和獠牙有助于迅速消灭猎物。"}
data[1020005] = { id = 1020005,  language = "实际是由众多微小的“灵”组成的寄生物，他们依附在泥里，组合成恐怖的形态吓走入侵者。"}
data[1020006] = { id = 1020006,  language = "深红色的火焰蛛天性凶残，喜欢蛰伏于暗处，一有机会就窜出来环抱敌人，利用足尖的高温毫不犹豫地终结敌人的性命。"}
data[1020007] = { id = 1020007,  language = "这种始终保持着奸诈笑容的生物看起来属于另一个时空，他们手持钢叉，动作迅速，通常情况下一击就直取敌人要害。"}
data[1020008] = { id = 1020008,  language = "由于长时间在地下寻找宝物，部分冒险者渐渐失去了心智，开始为了保护他们的“战利品”而疯狂地攻击入侵者。"}
data[1020009] = { id = 1020009,  language = "简单的防御性机械，因为会喷出长长的水柱而得名，据说曾被用于扑灭大火。"}
data[1020010] = { id = 1020010,  language = "怨念的集合体，总是发出凄凉的哭泣，雾气状若隐若现飘忽不定，没有人看得清它到底是个什么东西。"}
data[1020011] = { id = 1020011,  language = "连接时空的火之妖精。非常好战，随时准备用体内的火焰之力毁灭一切。"}
data[1020012] = { id = 1020012,  language = "一种邪恶的法术可以让死去的生物重新活过来。尽管看上去毫无生气，但是它们的确可以自由行动，并且充满攻击性。"}
data[1020013] = { id = 1020013,  language = "体型巨大的独眼恶魔，常被其他恶魔称作看门狗。虽然行动非常迟缓，但力大无穷不可小觑。"}
data[1020014] = { id = 1020014,  language = "在石巨人族里，它只能算是侏儒。只有双脚支撑着身体，露出呆滞而惊恐的表情，会用粗糙坚硬的头顶撞击敌人。"}
data[1020015] = { id = 1020015,  language = "连接时空的木之妖精。优雅而神秘，木妖看上去像个不解之谜，让人难以靠近。"}
data[1020016] = { id = 1020016,  language = "身形小巧的陆地恐龙，没有猎物能够逃脱它们的追击。它们十分狡猾，擅长耗尽猎物的体力再一口咬断它们的脖子。"}
data[1020017] = { id = 1020017,  language = "巨石傀儡稍微挪动身体就会消耗巨大的能量，所以它们平时基本一动不动，但这并不代表它们不会对入侵者发动最猛烈的攻击。"}
data[1020018] = { id = 1020018,  language = "有一种石巨人将自己化作坚不可摧的防御工事保卫家园。堡垒很难被破坏，并且会发射自然能量反击敌人。"}
data[1020019] = { id = 1020019,  language = "腐肉是渡鸦最喜爱的食物，它们常为此和同类发生争斗。锋利的爪子和喙帮助它们撕开任何猎物的皮肤。"}
data[1020020] = { id = 1020020,  language = "四足爬行恐龙，因浑身长满荆棘而得名。拥有异于同类的高超智慧，擅长操纵自然之力进行攻击。"}
data[1020021] = { id = 1020021,  language = "群居虫类，通常成群结队出现，发现猎物后便蜂拥而上，利用尾部的刺释放毒液麻痹猎物，待猎物失去知觉后再将其肢解。"}
data[1020022] = { id = 1020022,  language = "像圆盾一样的甲龙紧贴地面。它们的警惕性十分高，一旦进入防御姿态，任何人都无法伤它分毫。"}
data[1020023] = { id = 1020023,  language = "土人是大地之灵的化身，它们以泥土作为肉身，安静地徘徊在巨石旷野，保卫这里的一切。"}
data[1020024] = { id = 1020024,  language = "曾在众多知名战役中被广泛使用的防御机械，随着旧时代的结束与科技文明的毁灭而早已被遗忘。"}
data[1020025] = { id = 1020025,  language = "为了维护大地的活力，石龙穿梭于地底铲除不洁之物。它们并不好战，但破坏力却十分惊人。"}
data[1020026] = { id = 1020026,  language = "战场绞肉机。在上古战争中，毁灭者扮演了清道夫的角色。它的火力范围内不可能出现幸存者。"}
data[1020027] = { id = 1020027,  language = "一种鲜艳美丽但奇臭无比的植物。臭臭花所开之处方圆百米都能闻到恶臭的气味，它依靠这种气体来驱散天敌保护自己。"}
data[1020028] = { id = 1020028,  language = "来去无踪的刺骨猎人体内流淌着人类和猴子的血，身形娇小的他们异常敏捷，丛林为他们提供了天然的狩猎场。"}
data[1020029] = { id = 1020029,  language = "曼陀罗草长着一团团臃肿的瘤。这种迷一样的植物掌握了水魔法来抵御外敌。"}
data[1020030] = { id = 1020030,  language = "一种生长在淤泥回廊的巨型植物，拥有简单的意识，会对来自回廊外的生物发起进攻。"}
data[1020031] = { id = 1020031,  language = "半神，被众多原始部族作为图腾供奉。它们游弋在沼泽中，为沼泽生物提供庇护。"}
data[1020032] = { id = 1020032,  language = "一种歹毒的蘑菇怪。用单脚支撑巨大的蘑菇伞跳动，蘑菇伞的一侧隐藏着一张大口，随时准备吞噬它的敌人。"}
data[1020033] = { id = 1020033,  language = "刺骨部落的邪恶祭司。身体里流淌着人类和蟒蛇的血，拥有敏锐的洞察力和领悟力，掌握了某种大自然的力量。"}
data[1020034] = { id = 1020034,  language = "刺骨部落最勇猛的战士。身体里流淌着人类和豪猪的血，肥硕的身躯长满坚硬的刚毛，模糊的视力使他们无所畏惧。"}
data[1020035] = { id = 1020035,  language = "连接时空的水之妖精。喜欢恶作剧，会潜藏在丛林中用魔法困住猎物，玩弄或直接将其消灭。"}
data[1020036] = { id = 1020036,  language = "捕蝇草是蛰伏的丛林杀手，一旦猎物踏上它的茎脉便会张开满是粘液的大嘴，将猎物困住慢慢吞噬。"}
data[1020037] = { id = 1020037,  language = "繁殖力超强的丛林搬运者，不断挖掘地底隧道是它们短暂生命里唯一要做的事。没有什么侵略性，但破坏力却不容小觑。"}
data[1020038] = { id = 1020038,  language = "作为树人这个庞大族群中的一支，行动略迟钝的人形树妖讨厌争斗，但绝不允许有人侵犯他们的领地。"}
data[1020039] = { id = 1020039,  language = "它无所不在，它依附于所有淤泥沼泽生物上。在淤泥回廊中，它即是一切。当然也是它导致了这里一切生物的失控。"}
data[1020040] = { id = 1020040,  language = "数万年间，火山龟生活在深层的地下，以维护大地的稳定为使命。它们厚重的背壳下隐藏着强大的火焰之能。"}
data[1020041] = { id = 1020041,  language = "安沃氏族中的低阶巡逻恶魔。安沃斥候虽然力量不强，但相当敏捷，与它战斗时稍有不慎就可能丢掉性命。"}
data[1020042] = { id = 1020042,  language = "高脚战斗机械。具有攀爬功能，适应各种地形，常被用作执行任务，由于深埋地底所以保存完好。"}
data[1020043] = { id = 1020043,  language = "尽管旧时代早已结束，奉旧神之意守护火山的忠实仆从仍然矗立在那里，阻挡所有企图破坏家园之人。"}
data[1020044] = { id = 1020044,  language = "为了满足贪欲，安沃恶魔制造了这种低阶恶魔为他们开采矿脉、抢夺财物。"}
data[1020045] = { id = 1020045,  language = "用于战斗训练的机械。本身不具有主动攻击的能力，但是收到攻击时会发动反击。"}
data[1020046] = { id = 1020046,  language = "恐惧兽喜欢成群结队追踪活物，冒险者在这群利齿恶魔的眼里就像面包一样松软可口。"}
data[1020047] = { id = 1020047,  language = "拟人智慧机械。体型巨大，特制的黑铁巨拳是摧城拔寨的有效武器。"}
data[1020048] = { id = 1020048,  language = "曾是勇闯地下的冒险者，直到魅魔改变了他们的心智。不仅如此，魔鬼还授予了他们黑暗魔法，使得他们更加难以对付。"}
data[1020049] = { id = 1020049,  language = "最残虐狡诈的恶魔才能获得督军的名号。它统领众多的恶魔，时刻巡视着领地，三叉戟可以劈开任何盔甲。"}
data[1020050] = { id = 1020050,  language = "连接时空的暗之妖精。隐藏在阴影中时难以被发现，喜欢利用恐惧折磨猎物。"}
data[1020051] = { id = 1020051,  language = "安沃恶魔中的通灵者。擅长各种邪恶妖术，迷惑和欺骗是他的惯用伎俩。"}
data[1020052] = { id = 1020052,  language = "深渊巨兽修格斯是不折不扣的机器。它毫无怜悯之心，渴望碾碎身边的一切。安沃恶魔视这个怪物为他们的图腾。"}
data[1020053] = { id = 1020053,  language = "和圣兽相比狮子就像是初生的小狗。圣兽不仅能用利爪和强壮的身体攻击敌人，而且能用圣炎瞬间净化眼前的一切。"}
data[1020054] = { id = 1020054,  language = "无法获得超度的灵魂逐渐堕落成了游魂野鬼，它们通过吞噬灵魂来维持自身的存在。"}
data[1020055] = { id = 1020055,  language = "尽管庇护所早已毁灭，守护旧神之灵的武者仍然忠诚地在此看守，对妄图闯入庇护所的不法之徒实施惩戒。"}
data[1020056] = { id = 1020056,  language = "受到惩罚的堕落泰坦灵魂。即使离世了，魂魄依旧被灼热的圣炎炙烤，它的眼里只有怒火，疯狂地攻击任何活动的目标。"}
data[1020057] = { id = 1020057,  language = "第二代防御型器人，科技含量高，装备精良，有一夫当关万夫莫开之勇。"}
data[1020058] = { id = 1020058,  language = "创世神教的大僧侣之灵，最接近神灵的人类，从神那里学习了圣洁的光元素操控力。"}
data[1020059] = { id = 1020059,  language = "曾经驰骋沙场骁勇善战的狂战士之灵，离世后依旧勇武过人。浑身的蓝色火焰是他强大内心的具象化体现。"}
data[1020060] = { id = 1020060,  language = "连接时空的光之妖精。拥有与生俱来的神圣感和空灵感，掌握净化一切的神圣之力。"}
data[1020061] = { id = 1020061,  language = "在神官眼里，所有未经允许踏入神圣之地的家伙都是妄图亵渎神明的污秽，必须立刻净化掉。"}
data[1020062] = { id = 1020062,  language = "最精锐的法外狂徒之灵，曾被称为战争终结者。一旦受到征召，他们能短时间结束战争。"}
data[1020063] = { id = 1020063,  language = "理解世界运行规律、熟练运用所有元素之力的大巫师之灵。他们曾是这个大陆上最聪明的人。"}
data[1020064] = { id = 1020064,  language = "怨灵的集合体，常常附着在生物的遗骸上伺机偷袭冒险者。众多的受害者灵魂使它变得更加扭曲强大。"}
data[1020065] = { id = 1020065,  language = "大地之神盖亚的英灵，即便是消失后，她强大的魔法仍然能震慑生灵。旧神庇护所也因为她的存在而屹立不倒。"}
data[1020066] = { id = 1020066,  language = "宝箱描述"}
data[1020067] = { id = 1020067,  language = "就算在异鼠中，赤牙也是绝对的异类。被变异折磨到发狂的它会向任何入侵者发起攻击。"}
data[1020068] = { id = 1020068,  language = "精锐安沃恶魔先遣者的特殊癖好是使用利器挖出敌人的心脏。"}
data[1020069] = { id = 1020069,  language = "漫无目的的游魂。女性的哭泣声一直萦绕在其身边，它似乎永远在低语“加文”这个名字。"}
data[1020070] = { id = 1020070,  language = "曾经作为战斗武器而被驯化，但速龙学习了更残暴的技巧后干掉了主人。"}
data[1020071] = { id = 1020071,  language = "蝇王飞虱的亚种，数量稀少。通常猎物在觉察这些猎食者之前就已经被啃食干净了，这对被害者来说或许是件好事。"}
data[1020072] = { id = 1020072,  language = "被诅咒的土人，因此获得了更高一级的智慧。由于没有同类而感到孤独，时常控制不住体内邪恶的魔法而展开攻击。"}
data[1020073] = { id = 1020073,  language = "除了散发奇臭无比的气味，深棘更是长满了巨大的尖刺来保护自己免受攻击，没有任何人想遇到这种难缠的植物。"}
data[1020074] = { id = 1020074,  language = "半神，被众多原始部族作为图腾供奉。它们习惯游弋在沼泽中，为沼泽生物提供庇护。"}
data[1020075] = { id = 1020075,  language = "刺骨部落最勇猛的战士，身体里流淌着人类和豪猪的血。肥硕的身躯长满坚硬的刚毛，模糊的视力使他们无所畏惧。"}
data[1020076] = { id = 1020076,  language = "防御性能卓越的作战机械，被设计者伪装成训练机器人的样子，往往能在战场上起到奇效。"}
data[1020077] = { id = 1020077,  language = "像它的名字一样，剃刀在攻击时凶猛果断、毫不留情。倒在它利齿之下的亡魂不计其数。"}
data[1020078] = { id = 1020078,  language = "唤魔者是安沃恶魔中的绝对精英，除了掌握邪恶的黑暗魔法，它还负责将更多恶魔带到这个世界。"}
data[1020079] = { id = 1020079,  language = "护灵者统领拥有更加高超的战斗技巧和力量，无情地用武力审判试图破坏庇护所的敌人。"}
data[1020080] = { id = 1020080,  language = "博甘斯是与神对话的神官，因此也获得了圣光的祝福。信仰让他一直在帮助神明制裁所有污秽的灵魂。"}
data[1020081] = { id = 1020081,  language = "曾经是盖亚的神侍。因为爱上恶魔，所以死后的灵魂被盖亚诅咒，永远无法获得宁静。"}
data[1020082] = { id = 1020082,  language = "地精维斯克的第一桶金来自矮人王的墓穴，随后一发不可收拾。他那高额的通缉赏金据说还抵不上他偷盗财物的万分之一。"}
data[1020083] = { id = 1020083,  language = "远古时期统治大地的恶魔头领之一，因力量太过强大无法被击败，巨灵泰坦们只得将它封禁进了永恒虚空中。对时间之力的掌握让朝岁之灵在虚空中并没有消失，甚至这无尽的永恒更精炼了它的力量。\n终于，在新旧交替的时间流中，朝岁之灵找到了细微的裂缝，它将重新带领源源不断的大军回到这片大陆，拿回本来属于它的东西……"}
data[1020084] = { id = 1020084,  language = "朝岁之灵的爪牙，由它在永恒虚空中用散落的碎片制造而出，十分忠心。"}
data[1020085] = { id = 1020085,  language = "吸食了太多的尸体而变异的虱子，体型巨大且富有攻击性，只需一只就足够你受得了。"}
data[1020086] = { id = 1020086,  language = "皇宫的学者们为研究复活术而制造出的怪物，因为太过愚蠢而只被用来挖掘尸体。"}
data[1020087] = { id = 1020087,  language = "宵禁时期的恐怖巡查官，在变为幽灵后依旧徘徊在街头，企图让所有活着的东西乖乖“睡觉”。"}
data[1020088] = { id = 1020088,  language = "悲眉国的人经常把战亡的勇士与他们的战马一起下葬，这种奇怪的风俗巧合地制造出了两者相结合的恐怖骑士。"}
data[1020089] = { id = 1020089,  language = "王宫里最有趣的扮丑角色，同时也是皇家的秘密暗杀部队，为了更好地行使任务而主动提出被改造。"}
data[1020090] = { id = 1020090,  language = "由失败的永生之术制造而成的怪物，从它的脉动中能听到永不停止的尖叫，没人知道那团肉块中到底吸收了多少无辜的生命。"}
data[1020091] = { id = 1020091,  language = "生长在墓园里的古树，盘踞在墓碑和尸体之上。据说它身上的每一个树疤都对应着一个扭曲的灵魂。"}
data[1020092] = { id = 1020092,  language = "被拘束在瓶中的痛苦灵魂，生前遭受了难以忍受的酷刑。"}
