data[1020094] = { id = 1020094,  language = "专门被饲养在地宫里为皇家提供服务，它生产的毒液是皇室权术斗争里的绝好调味剂。"}
data[1020095] = { id = 1020095,  language = "由不同动物拼凑而成的怪物，一开始就是为了清除异己而创造的肉块。"}
data[1020096] = { id = 1020096,  language = "为了研究永生的秘密，悲眉国的学者们不惜以严酷的刑罚拷问自己，以此探究生命的边界。"}
data[1020097] = { id = 1020097,  language = "曾是国王眼前最红的小丑，后来一度失宠，但他残害民众的事迹又重新把国王逗得咯咯直笑。"}
data[1020098] = { id = 1020098,  language = "企图保护民众的女圣人，但最终沦为了狂热的牺牲品，大德兰因为背叛而变得冷酷无情。"}
data[1020099] = { id = 1020099,  language = "位置最高的御前学者，深入冥界的领地探索到了生命的奥秘，但却永远没有机会回来。"}
data[1020100] = { id = 1020100,  language = "当“疯国王”凯特终于取得他渴望的永生之后，面临的却是茫然的空虚，这永无止尽的时间让他变得更加疯癫。"}
data[1020101] = { id = 1020101,  language = "复活节出现的神秘石像，从何而来不得而知"}
data[1020102] = { id = 1020102,  language = "巨大的石像，坚硬无比"}
data[1020103] = { id = 1020103,  language = "军团蚁总是成群结队行动，它们的前颚强壮有力，并且可以喷出蚁酸，就算是沙漠中的大型动物也不敢轻易招惹这些小东西。"}
data[1020104] = { id = 1020104,  language = "据说是绝望之海中曾经活跃的盗贼团伙胡狼的一员，胡狼已经消失了多年，这个看起来像他们的躯壳显然不是真正的胡狼。"}
data[1020105] = { id = 1020105,  language = "可以在任何地面生长的肥硕仙人掌，感受到威胁的时候会向敌人发射遍布全身的钢钉，全身防御密不透风所以坚不可摧。“这种仙人掌的刺硬度堪比黑铁，被扎中要害足以致命。”"}
data[1020106] = { id = 1020106,  language = "双头秃鹫是一种非常猥琐的食腐鸟，它们敏锐的嗅觉能感知到百里之外的血腥，强壮有力的鸟喙和爪子可以像手术刀一样撕开猎物的尸体。"}
data[1020107] = { id = 1020107,  language = "金帐行者是绝望之海曾经盛极一时的金帐教廷国的僧侣，他们通过折磨自己的肉体来修行精神之力，金帐教廷国和胡狼一样早已神秘消失。"}
data[1020108] = { id = 1020108,  language = "绝望之海特有的蛇类，剧毒无比，被它盯上的猎物难逃一死，因此被称为冥王蛇。但如果只是注意毒液可要吃大亏了，它锋利的獠牙和毒液同样可怖。"}
data[1020109] = { id = 1020109,  language = "沙鱼并不是鱼类，因为可以在沙中穿梭而得名，只是它们极少移动，甚至可以呆在同一个地方长达数月，等待猎物落入它们的圈套。"}
data[1020110] = { id = 1020110,  language = "没有比风暴使者和眼前荒凉破碎的大地看起来更加和谐的了，不知道是环境产生了风暴使者还是它们创造了这里？无论如何，至少它们比我们看起来更像这里的主人，如果不想发生冲突，最好恭敬地绕过它们。"}
data[1020111] = { id = 1020111,  language = "金帐教廷的主要战力，圣教军坚信教皇的祝福使他们身体能够承受非同寻常的打击，因此他们作战时勇猛无比毫无畏惧。"}
data[1020112] = { id = 1020112,  language = "在胡狼消失的多年之后，沙漠中仍然流传着破坏者的传说，他们比一般的人类魁梧很多，力量惊人，是胡狼攻城拔寨，所向披靡的利器。"}
data[1020113] = { id = 1020113,  language = "强击龙实际是一种蜥蜴，皮肤硬如磐石，身上布满尖刺，好战又极具破坏力，所以获得了令人胆寒的“龙”的称号。"}
data[1020114] = { id = 1020114,  language = "沙粒在某种力量的驱使下仿佛获得了生命，流沙魔看起来没有欲望，没有目的，四处游荡，但挑战它的时候一定要当心。"}
data[1020115] = { id = 1020115,  language = "这个胡狼前锋看起来，准确来说是装扮看起来有所不同，她应该是一名女性，精致的刀刃上刻着“赫莎”的字样。"}
data[1020116] = { id = 1020116,  language = "这个风暴使者看起来吸收了过多的能量，因此感觉十分暴躁，四处宣泄。请不要随意接近他，当心触电。"}
data[1020117] = { id = 1020117,  language = "受到沙之眼神秘能量影响而变异的强击龙亚种，体型更大。原本就好斗的强击龙在变异的影响下成为了更加凶残嗜血的品种。"}
data[1020118] = { id = 1020118,  language = "绝望之海的人们常常用廷达洛斯的故事来管教不听话的孩子，大多数人认为它只是神话中的怪兽。事实上，它也仅仅苏醒过寥寥的几次，据研究金帐教廷的消失似乎与它有密切的关系。"}
data[1020119] = { id = 1020119,  language = "如果说异鼠的牙齿算是锋利，那么噬心鼠的牙齿简直是削铁如泥。许多冒险者都命丧他的利齿之下，甚至心脏都被咬噬。噬心鼠也因此得名。"}
data[1020120] = { id = 1020120,  language = "血蛭的身体流动着红色的血液，但他们的血液却散发着一股恶臭，一股腐烂的恶臭。"}
data[1020121] = { id = 1020121,  language = "来自炼狱的火焰，旨在给予一切事物苦痛和折磨。"}
data[1020122] = { id = 1020122,  language = "挥舞的翅膀散发着蓝色的火星，任何东西被溅到都会立刻燃烧起来。"}
data[1020123] = { id = 1020123,  language = "曾经组成泥浆怪的“灵“以一种更恐怖的形态融合在了一起。他们现在不仅能吓你，还能烫你。"}
data[1020124] = { id = 1020124,  language = "苍蓝色的蜘蛛，比起一般的火焰蛛杀伤力更强。但是他们不再蛰伏在暗处袭击冒险者了，因为已经没有必要了。"}
data[1020125] = { id = 1020125,  language = "不同于流放恶魔，虚位恶魔刚刚来到这个时空，他们迫切的想要释放自己无处发泄的力量。"}
data[1020126] = { id = 1020126,  language = "狂乱冒险者是完全化身为暴虐的冒险者。他们的心智已经完全丧失殆尽，只剩下无尽的疯狂和破坏。"}
data[1020127] = { id = 1020127,  language = "锈迹斑斑的水龙，但依然能活动。喷出的水柱也变得具有腐蚀性。"}
data[1020128] = { id = 1020128,  language = "这些怨念的集合体在神秘力量的扭曲下变成了恶灵，他们存在唯一的目的就是夺取一切活物的生命。"}
data[1020129] = { id = 1020129,  language = "火之妖精体内的火焰发生了异变，他们很高兴看到自己能更轻易的把冒险者烧成灰了。"}
data[1020130] = { id = 1020130,  language = "比起行动软绵绵的尸犬，腐烂狂犬更像是一只活生生的猎犬，但更凶狠,身体也腐朽的更残破。"}
data[1020131] = { id = 1020131,  language = "这只水蛭口中的血液已经变得乌黑，但他无时不刻在渴求着新鲜的血液补给。"}
data[1020132] = { id = 1020132,  language = "这团紫色的火焰能够燃尽一切灵魂"}
data[1020133] = { id = 1020133,  language = "众火蝠的领袖。火蝠王翅膀扇出的火星能制造小型爆炸，你一定不想在狭窄的空间遇到它。"}
data[1020134] = { id = 1020134,  language = "莫咖毒浆组成的身躯中似乎寄宿着什么强大的\"灵\"，当你听到“莫咖莫咖”的喃喃声时赶紧逃命吧。"}
data[1020135] = { id = 1020135,  language = "喀什并不满足于杀死猎物，她更热爱把猎物抓到自己的地盘，然后让他体会痛苦的味道。"}
data[1020136] = { id = 1020136,  language = "谁也不知道奥克兰在洞里待了多少年了，但是从他手中那柄破剑上的血迹来看，他似乎从没有闲着。"}
data[1020137] = { id = 1020137,  language = "使用最大功率输出，喷出的水柱甚至能冲破岩石。"}
data[1020138] = { id = 1020138,  language = "皮拉特太喜欢高温，他甚至能把自己的同族给点着了。"}
data[1020139] = { id = 1020139,  language = "安沃恶魔领主沃尔多克无论什么时候都挂着他最喜欢的笑容，尤其是把你撕成碎片的时候。"}
data[1020140] = { id = 1020140,  language = "在被冒险者打败之后，被扭曲空间的力量重新复活。在鲜血与仇恨的诅咒之下变得更加凶暴，他发誓不会放过任何一个胆敢挑战他的冒险者。"}
data[1020141] = { id = 1020141,  language = "布鲁诺是一只忠诚的狗狗，生前如此，死后也是如此。"}
data[1020142] = { id = 1020142,  language = "邪能晶矿中残留的晶体物质组成了这种生物，他们并不会主动攻击敌人，但面对敌人的攻击也绝不会坐以待毙"}
data[1020143] = { id = 1020143,  language = "本应承载自然之力的木妖受到了扭曲能量的影响，整个身体都变为了红色，看上去就像是红衫木的树枝一般。所以也被称作杉木妖。"}
data[1020144] = { id = 1020144,  language = "作为顶级猎食者，烈龙虽然可以通过晶体矿石获取能量，但是对于他们来说，脆弱的冒险者才是最好的猎物。"}
data[1020145] = { id = 1020145,  language = "晶体石像的身体由体积较大纯度较高的晶矿组成，他们的身体坚不可摧，他们的重击能摧毁一切。但只要你不主动招惹，就不会引起他们的怒火"}
data[1020146] = { id = 1020146,  language = "这些魔能中枢外部由坚硬的晶体壳组成，内部则是翻动的扭曲能量。任何胆敢靠近的生物都会被这股扭曲能量化作的能量光束轰杀。"}
data[1020147] = { id = 1020147,  language = "寒鸦以晶体喂食，他们的喙能轻易地啄碎岩石。"}
data[1020148] = { id = 1020148,  language = "这种恐龙身上长满了形式钢铁的荆棘，但是却可以根据他们自己的意志肆意弯曲，甚至能从地下钻出进行攻击。"}
data[1020149] = { id = 1020149,  language = "腐血虱喜欢吸食腐败的血液，如果没有食物，他们会杀死猎物再把猎物储藏起来等待血液逐渐腐败。"}
data[1020150] = { id = 1020150,  language = "岩壳龙浑身包括着坚硬的岩石外壳，并且尾巴末端有一颗实心的石球，密度远高于身体其他岩石部分。"}
data[1020151] = { id = 1020151,  language = "带有腐蚀性的油污组成了油怪的身体。其他物质只是占上一点这种油污，立即就会被腐蚀。所以在油怪的行径上总会留下长长的腐蚀印记。"}
data[1020152] = { id = 1020152,  language = "古代机械装置的一种型号，专门用于对场地进行守卫工作。他的防卫性能非常可靠。"}
data[1020153] = { id = 1020153,  language = "火晶龙穿梭于岩石之中，他们坚硬的身体有着极高的温度，甚至能够熔化岩石。"}
data[1020154] = { id = 1020154,  language = "阿缺每天独自躲在晶矿的角落里，不和其他的碎晶怪一起玩耍，因为怕把他们弄碎。"}
data[1020155] = { id = 1020155,  language = "作为木妖的领导者，一定要有一个响亮的名号。哈雷奎因就是这么想的。"}
data[1020156] = { id = 1020156,  language = "巨石傀儡偶会聚集在一起，彼此战斗，而这场大混战中最后的胜者就是石体战神。"}
data[1020157] = { id = 1020157,  language = "魔能核心内部是纯粹的扭曲能量，它会扭曲周围生物的心智，并且毁灭试图进犯的敌人。"}
data[1020158] = { id = 1020158,  language = "传说有一只寒鸦，长着细小尖锐的牙齿，嗜血成性，连自己的同类都会被其捕食。"}
data[1020159] = { id = 1020159,  language = "因为好斗，碎荆的身上总是带着伤。不过冒险者之间有一句老话“受伤的敌人才是最危险的”"}
data[1020160] = { id = 1020160,  language = "岩壳龙身体上的岩壳会随着年龄的增长，密度越来越大，导致他们身体的重量也越来越大，到最后会像一座小山一样沉重。"}
data[1020161] = { id = 1020161,  language = "铁熔怪是独一无二的，他的身体既是熔化的铁水，普通的武器很难对他们造成什么伤害。"}
data[1020162] = { id = 1020162,  language = "在冒险者协会的记录中，很少发现会主动攻击的古代机械装置，他们一度以为古代机械没有这种特性。但事实证明他们错了。"}
data[1020163] = { id = 1020163,  language = "即便是最强大的冒险者，在遇到赤体邪龙时也会忍不住双腿发抖。每次在击败对手之后，邪龙还会发出戏谑的笑声再结束对手可怜的生命"}
