data[1020458] = { id = 1020458,  language = "混沌虚空孕育而成，暴躁好斗，当两个角兽相遇时，无关胜负，只决生死！胜者生，败者亡！"}
data[1020459] = { id = 1020459,  language = "混沌虚空孕育而成，能够跋涉于不同的世界之间。他们见遍不同世界的冷暖，如过客一般冷漠，视世间万物如蝼蚁。"}
data[1020460] = { id = 1020460,  language = "和吉瑞总是成双结对的出现，当他们出现的时候伴会随着好运或者厄运，赌徒们期待着他们的到来！"}
data[1020461] = { id = 1020461,  language = "和吉利总是成双结对的出现，当他们出现的时候伴会随着好运或者厄运，赌徒们期待着他们的到来！"}
data[1020462] = { id = 1020462,  language = "混沌虚空划分无数空间，而力王则是一个空间内最终活下来的角兽，他经历了上万次的战斗，最终独活成王！"}
data[1020463] = { id = 1020463,  language = "奥古斯曾踏遍万千世界，但他却不像其他混沌行者一般冷眼旁观，每一个世界他都曾亲历，他曾为将相帝王，也曾是贩夫走卒，但他始终是一个独行者。"}
data[1020464] = { id = 1020464,  language = "混沌虚空孕育而成，和吉斯总是成双结对的出现，当他们出现的时候伴会随着好运或者厄运，赌徒们期待也恐惧着他们的到来！"}
data[1020465] = { id = 1020465,  language = "混沌虚空孕育而成，和吉鲁总是成双结对的出现，当他们出现的时候伴会随着好运或者厄运，赌徒们期待也恐惧着他们的到来！"}
data[1020466] = { id = 1020466,  language = "混沌虚空孕育而成，曾以石像的存在方式记录于某上古文献，如今再次踏足这片世界，不知意欲何为？"}
data[1020467] = { id = 1020467,  language = "文献记载，法老芬尼斯具备其他石像所不具备的诅咒能力，任何敢于探索、打听、研究其传说的人最终都会死于非命！"}
data[1020468] = { id = 1020468,  language = "文献记载，艾姆站在权力金字塔的顶端，具有绝对的权力。人们对艾姆的崇拜近乎疯狂，仅仅是艾姆的名字就具有不可抗拒的魔力，他们以亲吻艾姆的脚而感到自豪。"}
data[1020469] = { id = 1020469,  language = "混沌虚空孕育而成，这些异形是天生的野心家，追求极致的地位与权利，拥有极其强烈的控制欲望，肆意掠夺！"}
data[1020470] = { id = 1020470,  language = "队长多利亚拥有不择手段的野心和破坏欲望，一直窥视帝王的宝座。多利亚本身冷酷无情，情绪变化很不稳定，时而冷静，偶尔易怒。一旦展开大杀戒，连身边的下属都不会放过。"}
data[1020471] = { id = 1020471,  language = "作为异形的王者，库尔德惯有冷酷的作风和阴险毒辣的手法，号称“邪恶帝王”。厌恶一切美好的事物，冷血狡猾，但有着一股惊悚的人格魅力。"}
data[1020472] = { id = 1020472,  language = "混沌虚空孕育而成，他们可以引导自己进入恍惚的状态，与妖魔鬼怪直接沟通，从而随心所欲得行使他人无法可及的力量。"}
data[1020473] = { id = 1020473,  language = "通灵者基德可与妖首鬼王沟通，施展他们强大的力量，精怪灵鬼在面对基德的时候只能瑟瑟发抖，弱小者更会口吐白沫进而昏厥。"}
data[1020474] = { id = 1020474,  language = "法塔赫平日里面善且不起眼，即便出现在你的面前，也会下意识的将其忽略。然而千万不要试图激怒法塔赫，否则你面临的将是无穷无尽的妖魔鬼怪，是真正的地狱！"}
data[1020475] = { id = 1020475,  language = "混沌虚空孕育而成，似狼非狼，凶暴残忍，对野兽有着天然的威慑力，再凶猛的老虎也会宛若猫咪一般乖巧顺服。"}
data[1020476] = { id = 1020476,  language = "屠夫嗜杀，喜好将顺服的野兽残杀，后肢解、开膛、堆积它们的四肢和内脏，然后静静欣赏，慢慢品尝。"}
data[1020477] = { id = 1020477,  language = "兽王卡尔加德，自负且好战。战斗中会陷入彻底疯狂而进行无尽的杀戮，清醒后又会因过度的杀戮对神进行忏悔。当然，这些都只是表象，他只是在掩饰他的残暴不仁！"}
data[1020478] = { id = 1020478,  language = "混沌虚空孕育而成，他们自称神的使者，侵入世界后广收教徒，四处宣扬真、善、美，当这些教徒深信不疑时，将完全迷失自我。"}
data[1020479] = { id = 1020479,  language = "文献记载，炽天使从不直接过问人间的种种不道德，只有在安息之中，在神的无尽的爱中，炽天使才与人类同在。然而他们是什么？却从来没有明确的文献记载。"}
data[1020480] = { id = 1020480,  language = "混沌入侵后，最著名的天使——大天使加洛，是最接近神的天使，被称为似神者。相传加洛会引导那些“异教徒”走向“彼岸”，并审判他们死后的命运。"}
data[1020481] = { id = 1020481,  language = "混沌虚空孕育而成，妖娆的身姿与姣好的面容，天然引起男性的爱慕，意志薄弱者甚至会被其魅惑而失去心智。"}
data[1020482] = { id = 1020482,  language = "每一只魅魔都有无可阻挡的魅力，而玛姬就是其中的佼佼者。玛姬举手投足之间即可让男性神魂颠倒，甘愿为玛姬付出任何代价甚至生命！"}
data[1020483] = { id = 1020483,  language = "没有任何人，是的包括女性，能够抵挡洛蒂的魅力，相传她曾化为妖狐魅惑了世间最强的女性帝王，最终颠覆了这异常强盛的国家，离开之际她留下了一句话：玩玩而已。"}
data[1020484] = { id = 1020484,  language = "拥有高深莫测的能力，可以吸收世间万物的形态，转为自身的形态，死亡后随机变化成其他怪物"}
data[1020485] = { id = 1020485,  language = "拥有比初级元神更强大的变化能力，可以变化成更为强大的怪物"}
data[1020486] = { id = 1020486,  language = "由混沌虚空幻化而成，吸收了廷达洛斯和诺达尼斯的能力，拥有多种形态并且随机变化，要想击败它可以说是痴人说梦"}
data[1020487] = { id = 1020487,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。狼首人身，相传所有的狼人都拥有变身的强大能力，但并非所有狼人都能觉醒这个能力。"}
data[1020488] = { id = 1020488,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。他们没有固定的形体，能够适应各种环境，被称为“宇宙中的生存者”。"}
data[1020489] = { id = 1020489,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。龙兽对领地和食物资源保持强烈的占有欲和防卫本能，任何想要接近的生物都被其视为入侵者。"}
data[1020490] = { id = 1020490,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。白猿通常结伴出现，互相慰藉，协同作战，同生共死。"}
data[1020491] = { id = 1020491,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。猿兽通常结伴出现，互相慰藉，协同作战，同生共死。"}
data[1020492] = { id = 1020492,  language = "贝杜尔原本只是一个普通的狼人战士，但他通过不断的战斗和锻炼，提升自己的力量和技能，逐渐成为狼人传说中的强大战士"}
data[1020493] = { id = 1020493,  language = "麦德斯拥有极强的欺骗能力，他精明且狡猾，经常利用自己的能力来欺骗以及捕获猎物，并乐此不疲。"}
data[1020494] = { id = 1020494,  language = "指挥官奇拉是龙王萨德贝克的仆从，极其忠诚且异常谄媚。他将服侍龙王作为其最高使命，无论是穿衣吃饭，都会由其代劳。龙王萨德贝克非常信任他，所有事物也交给奇拉打理。"}
data[1020495] = { id = 1020495,  language = "精与钢曾经陷入过绝境濒临死亡， 恰巧被杨王柳后遇见，将精钢复活。从此，精钢实力大进，已经是白猿中赫赫有名的侠侣。"}
data[1020496] = { id = 1020496,  language = "精与钢曾经陷入过绝境濒临死亡， 恰巧被杨王柳后遇见，将精钢复活。从此，精钢实力大进，已经是白猿中赫赫有名的侠侣。"}
data[1020497] = { id = 1020497,  language = "芬鲁斯是狼人社会的领袖，他拥有强大的战斗力和领导力，此外还拥有着独特的变身能力，能够在变身后释放出巨大的狼之力量。"}
data[1020498] = { id = 1020498,  language = "凯撒作为史莱姆一族的首领，同时也被认为是混沌虚空中的一种掌控者。他能够自我分裂，于短时间内分裂成一个庞大的史莱姆族群，甚至在面临生命危险时重新聚合以获得新生"}
data[1020499] = { id = 1020499,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。他们没有固定的形体，能够适应各种环境，被称为“宇宙中的生存者”。"}
data[1020500] = { id = 1020500,  language = "龙王萨德贝克，龙兽的王者，他傲慢、享乐、懒惰。他很可能掌控了空间能力，可以随时随地召唤其他龙兽服侍自己。但萨德贝壳极其强大，其他龙兽只能服从。"}
data[1020501] = { id = 1020501,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。龙兽对领地和食物资源保持强烈的占有欲和防卫本能，任何想要接近的生物都被其视为入侵者。"}
data[1020502] = { id = 1020502,  language = "杨王柳后，拥有着奇异的能力：当白猿陷入濒死时，他们可消耗自身混沌能量，将濒死之猿复活，复活的白猿将突破自身壁垒，变得更加强大！"}
data[1020503] = { id = 1020503,  language = "杨王柳后，拥有着奇异的能力：当白猿陷入濒死时，他们可消耗自身混沌能量，将濒死之猿复活，复活的白猿将突破自身壁垒，变得更加强大！"}
data[1020504] = { id = 1020504,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。人首鱼身，均为女性。她们有着沁人心脾的美妙歌声，让人不自觉的陷入幻觉，所见缤纷绚丽，所闻天音靡靡……"}
data[1020505] = { id = 1020505,  language = "受混沌虚空影响，雷兽影化过程中诞生的雷影，雷影体内蕴含的阴雷之力，虽不如母体强大，但仍然无可匹敌。"}
data[1020506] = { id = 1020506,  language = "人鱼公主可可，人鱼一族的公主之一，她以圣洁之姿示人，被人鱼一族视为崛起的希望。然而其美若天仙，心如蛇蝎，欺骗了所有人鱼。"}
data[1020507] = { id = 1020507,  language = "作为雷兽与影兽力量的杰出继承者，雷之子兼具雷电与暗影之力，其招式精妙且致命，能够自如操控雷电元素与暗影元素。"}
data[1020508] = { id = 1020508,  language = "塞莉儿作为人鱼一族的女王，拥有着绝美之貌，天籁之声。塞莉儿出现之处枯木逢春、枯骨生肉。她将幻境变为现实，被所有人鱼称为“奇迹女王”。"}
data[1020509] = { id = 1020509,  language = "受混沌虚空影响，雷兽影化过程中诞生的虚实结合体，影兽时常隐匿于雷兽阴影之中，瞬间同时发动致命攻击，他们的存在的本身就是对现实与虚幻边界的挑战。"}
data[1020510] = { id = 1020510,  language = "混沌虚空孕育而成，常年栖息于混沌虫洞。时空逆转，空间交错，降临巴萨坦。体型庞大，犬首人身。他们肌肉如山，力大无穷，惯以蛮力攻击，如军队一般，成群出现。"}
data[1020511] = { id = 1020511,  language = "犬巨人军师，能够巧妙地指挥其他犬巨人协同作战，据传是因为他的存在，希图斯才能够建立出犬巨人军队，所向披靡。"}
data[1020512] = { id = 1020512,  language = "希图斯是犬巨人族群中的首领，身形巍峨，威势惊人，不仅力量巨大，更具有超凡智慧与领导力，大智若愚，其亲手建立的犬巨人军队却被外人认为是其军师所为。"}
data[1020513] = { id = 1020513,  language = "寒冰哨兵是冰霜嚎月麾下的忠诚卫士，它们拥有厚重的毛皮，能够在极寒环境下自由行动。寒冰哨兵的爪子锋利如刀，能够轻易撕裂冰层，它们的速度极快，善于在冰雪覆盖的地形中伏击猎物。"}
data[1020514] = { id = 1020514,  language = "影界潜行者是混沌裂牙的密探，它们的身体由流动的暗影组成，几乎能够完美融入任何阴影之中。潜行者擅长隐匿，常常在敌人毫无察觉的情况下发动致命一击。"}
data[1020515] = { id = 1020515,  language = "冰霜嚎月与混沌裂牙是双生的狼神，它们不仅是极地腐穴的守护者，同时也是混沌与冰霜两种对立力量的化身，它们的存在维持着这片领域的平衡与秩序。"}
data[1020516] = { id = 1020516,  language = "混沌扭曲者是碎界者直接从混沌能量中召唤而生，它们可以制造小型的时空扭曲，干扰视线，使追踪变得困难。"}
data[1020517] = { id = 1020517,  language = "时空流浪者是被碎界者从不同宇宙召唤而来，它们能够在现实与虚幻之间自由切换，难以捕捉。"}
data[1020518] = { id = 1020518,  language = "当神明碎片之野与黑暗腐化之道交汇时，一股未知的力量从中觉醒。这股力量汇聚了两个空间的精华与腐化，形成了一个拥有自我意识的实体——碎界者。它既不是纯粹的混沌生物，也不完全是秩序的守护者，而是介于两者之间的存在，掌握着操控现实与虚幻的双重能力。"}
data[1020519] = { id = 1020519,  language = "星之精灵是盖亚最亲密的伙伴之一，它们象征着自由和变化。它们在天空中自由翱翔，随时准备响应盖亚的召唤。它们不仅是战斗中的得力助手，也是传递信息的重要使者。"}
data[1020520] = { id = 1020520,  language = "星辉使者是盖亚在神域裂隙中获得的新力量的体现。它们由混沌之力和星辰之力融合而成，象征着盖亚对黑暗面的理解与掌控。星辉使者是盖亚意志的执行者，负责清除那些威胁世界平衡的存在。"}
data[1020521] = { id = 1020521,  language = "大天使加洛企图通过净化仪式削弱大地之母盖亚的力量，然而，这场净化并没有如愿以偿。当加洛启动净化仪式时，盖亚的力量从大地深处涌出，席卷了整个净化现场。她的意志与大地融为一体，成为新的混沌神祇。"}
data[1020522] = { id = 1020522,  language = "一位古老的沙漠守护者利用古老的金属和沙尘之力，打造了沙尘气息。沙尘气息不仅能够操控沙尘，还能释放强大的沙尘风暴，保护沙漠中的生灵免受外来威胁。"}
data[1020523] = { id = 1020523,  language = "在一次神域裂隙的动荡中，混沌之力与沙尘之力发生了剧烈的碰撞，形成了混沌沙灵。混沌沙灵不仅拥有混沌之力，还融合了沙尘之力，成为了一种独特的存在。"}
data[1020524] = { id = 1020524,  language = "阿戈诺斯是一个巨大的沙漠巨兽，其主体由不断流动的沙粒构成，看起来像是一个由沙子组成的庞大漩涡。在漩涡中心，有一颗由纯金和红宝石镶嵌的巨大眼球，闪烁着狡诈的光芒。"}
data[1020525] = { id = 1020525,  language = "在时蚀巨沼的昏暗环境中，冥渊触灵如同潜伏在阴影中的幽灵，它们的触手在泥浆中悄无声息地游动，等待着下一个猎物的到来。"}
data[1020526] = { id = 1020526,  language = "在时蚀巨沼的深处，触灵巨爵如同一个漂浮在沼泽之上的巨大阴影，它的触手在黑暗中悄无声息地游动，仿佛在寻找着下一个猎物。"}
data[1020527] = { id = 1020527,  language = "由寄生体进化而成的半透明噬时兽，能吞噬时空能量重塑躯壳，随混沌环境改变形态。核心“光烁之石”嵌于腐化神骸中，触须释放寄生孢子侵蚀活体，遇险则液化重组、重新寄宿，在岩岛沼泽间游荡，见证神明法则的畸变溃烂。"}
data[1020528] = { id = 1020528,  language = "扭曲的机械残骸与混沌黏液融合的畸形生物，拖着断裂的青铜锁链在倒悬神庙中爬行。体表齿轮不断渗出腐蚀时空的紫色脓液，攻击时会引发小范围时空紊乱。"}
data[1020529] = { id = 1020529,  language = "佩戴破碎祭司面具的时空幽灵，三枚逆向转动的齿轮眼能同时观测多重时间线。手持由\"被遗忘祷文\"铸成的时漏剑，每次斩击都会带出平行时空的残影。"}
data[1020530] = { id = 1020530,  language = "倒悬圣所中央悬浮着逆向跳动的机械神格，十万根断裂的信仰锁链如血管般蠕动。展现旧神陨落的永恒瞬间——神血在时停领域中凝固成金色星河，而整个战场会随着神格每次脉动重构空间法则，立柱与齿轮在虚空中不断重组为新的杀戮舞台。"}
data[1020531] = { id = 1020531,  language = "灭世歌姬可将她的歌声传遍现实世界，通过歌声将世界万物拉入由她创造的虚拟世界“永恒梦境”。在这里，灭世歌姬近乎拥有神的支配权，随意操控他人，无所不能。"}
data[1020532] = { id = 1020532,  language = "在遗忘之穴最深处，沉睡千年的古老岩石因贪婪者的挖掘而苏醒。它本是洞穴之灵，如今却成为守护遗忘之穴的愤怒化身。"}
data[1020533] = { id = 1020533,  language = "古代祭司的骸骨被某种黑暗力量侵蚀，形成一具由腐化骨骼与紫色幽光构成的庞然大物。它曾是旷野的守护者，如今却成为巨石旷野扭曲生态的具象化体现。"}
data[1020534] = { id = 1020534,  language = "不久之前，淤泥回廊曾遭遇一场神秘的能量风暴侵袭。一只普通的飞蛾偶然间闯入了风暴的核心区域，在狂暴能量的疯狂洗礼下，它蜕变为令人胆寒的幽影幻蛾。它的眼睛犹如深邃的黑洞，能够洞察一切进入旷野的生物的内心恐惧与欲望。"}
