data[1150073] = { id = 1150073,  language = "坐落在天空的堡垒，这里也是传说中的“黑翼之巢”，可能一不留神，就有鸟兽从你头上飞过！千万小心，别被鸟砸到，应该会很痛！"}
data[1150074] = { id = 1150074,  language = "许愿湖"}
data[1150075] = { id = 1150075,  language = "静谧的沼泽深处有个名为许愿湖的地方，相传湖里住着一位善良的仙女，她会满足每个人的愿望，狂热的人们纷纷而至，最终只在湖边留下杂乱的足迹。"}
