data[1150100] = { id = 1150100,  language = "混沌虫洞时空逆转，空间交错，曾经的洞穴与旷野于此形成死亡矿井，强大的狼王芬鲁斯统领着此处空间。"}
data[1150101] = { id = 1150101,  language = "混沌虫洞时空逆转，空间交错，淤泥布满裂谷，这里到处都是史莱姆，它们栖息于泥浆，隐匿于裂缝，这里是凯撒的后花园。"}
data[1150102] = { id = 1150102,  language = "混沌虫洞时空逆转，空间交错，一半神邸，一半鬼城，神鬼交杂，能否共存？在这里，无论人、鬼、神，均屈服于龙王萨德贝克"}
data[1150103] = { id = 1150103,  language = "混沌虫洞时空逆转，空间交错，白猿栖身熔洞，活跃沙海。灼热与干枯引起梦幻般的幻觉，这里恍若梦幻乐园。"}
data[1150104] = { id = 1150104,  language = "虚无空间"}
data[1150105] = { id = 1150105,  language = "混沌虫洞深处的虚无空间栖息着强大的生物，这些生物拥有着不可思议的能力：它们有的能够穿梭时空，有的可以将一切腐蚀……其中的主宰甚至以星球喂食。"}
data[1150106] = { id = 1150106,  language = "珊瑚林"}
data[1150107] = { id = 1150107,  language = "混沌虫洞时空逆转，空间交错，绚丽珊瑚奇景埋骨累累，绝妙人鱼歌声沁人耳目。此处绝美缤纷？亦或残破腐朽？"}
data[1150108] = { id = 1150108,  language = "迷幻水域"}
data[1150109] = { id = 1150109,  language = "混沌虫洞深处的迷幻水域栖息着强大的生物，这些生物拥有着不可思议的能力：它们有的能够藏匿于水底，有的可以在水中变化为万物，其中的主宰甚至有着多个阶段，每个阶段都极具强大！"}
data[1150110] = { id = 1150110,  language = "起源殿堂"}
data[1150111] = { id = 1150111,  language = "混沌虫洞时空逆转，空间交错，光与暗相互碰撞又互相渗透，在这片奇异殿堂的核心，出现了由雷兽影化而成的影兽，它们共同统治着起源殿堂。"}
data[1150112] = { id = 1150112,  language = "祈愿天池"}
data[1150113] = { id = 1150113,  language = "混沌虫洞时空逆转，空间交错，天空与湖水无缝衔接，新的秩序悄然建立，犬巨人族崛起，像是连接天池的桥梁，坚韧与神秘。"}
data[1150114] = { id = 1150114,  language = "熔岩之心"}
data[1150115] = { id = 1150115,  language = "混沌虫洞深处的熔岩之心栖息着强大的怪物，同时混乱异常：火焰领主肆意游荡，袭击一切眼前的生物；熔岩之灵群居隐匿于暗处，伺机袭击落单怪物；主宰熔岩巨兽震慑所有怪物，始终保持警惕。"}
data[1150116] = { id = 1150116,  language = "极地腐穴"}
data[1150117] = { id = 1150117,  language = "混沌虫洞时空逆转，空间交错，寒冷的冰霜与矿洞的金属构造交织在一起，冰封的矿车静止在时间的裂缝中，铁镐和轨道在混沌之力的作用下扭曲变形，仿佛被一种不可名状的力量重塑。"}
data[1150118] = { id = 1150118,  language = "腐化旷野"}
data[1150119] = { id = 1150119,  language = "混沌虫洞时空逆转，空间交错，这里是光明与黑暗交织的战场，神明的碎片与混沌之力在这里碰撞，产生了前所未有的能量波动。对于那些敢于挑战未知的冒险家而言，这里是试炼之地，也是机遇之所。"}
data[1150120] = { id = 1150120,  language = "生命森林"}
data[1150121] = { id = 1150121,  language = "混沌虫洞深处的生命森林栖息着强大的怪物，这些生物拥有着不可思议的能力：食人花大王盘踞沼泽地带，发出低沉的声音吸引猎物靠近；耶梦加得守护着古老的遗迹，任何试图接近者都会遭到它的猛烈反击；生命之源由树木、藤蔓、花朵等自然元素构成，看起来就像是森林本身幻化出的巨大生物，似乎拥有治愈能力和操控植物生长的力量。"}
data[1150122] = { id = 1150122,  language = "神域裂隙"}
data[1150123] = { id = 1150123,  language = "混沌虫洞时空逆转，空间交错，神罚之裂与混沌神庙这两个原本相距甚远的地点交织在一起，形成了一片充满未知与危险的领域。这里是混沌之力与古老神明遗留下来的能量相互作用的结果，充斥着混乱与不稳定的元素。"}
data[1150124] = { id = 1150124,  language = "灼热地狱"}
data[1150125] = { id = 1150125,  language = "混沌虫洞时空逆转，空间交错，奈落之城与干涸之泉两个截然不同的地域交织融合。这里的天气也异常多变，白天酷热难耐，夜晚则冷风刺骨。偶尔会有沙尘暴席卷而来，使得视线受阻，行动困难。"}
data[1150126] = { id = 1150126,  language = "冰冠王座"}
data[1150127] = { id = 1150127,  language = "混沌虫洞深处的冰冠王座栖息着强大的怪物，这些生物拥有着不可思议的能力：记忆窃取者驻守寒冰走廊，入侵者会漫无目的的闲逛，逐渐迷失自我；冰冠公主与王子则生活在冰霜庭院，庭院遍布冰雕，这些冰雕都是曾经来挑战的英雄；巫妖之主独自被封印在冰封神殿的一座巨大冰冠中，这里无人踏足。"}
data[1150128] = { id = 1150128,  language = "时蚀巨沼"}
data[1150129] = { id = 1150129,  language = "混沌虫洞时空逆转，空间交错，这里是神创与腐化的战场，亦是过去与未来的坟场：造物主遗留的巨型岩石与淤泥回廊的剧毒沼泽在虫洞引力下不断破碎、重组，形成漂浮的岩岛、倒流的泥河与凝固在时间断层中的半透明生物残影。"}
data[1150130] = { id = 1150130,  language = "渊瞳圣殒墟"}
data[1150131] = { id = 1150131,  language = "混沌虫洞时空逆转，空间交错，这座本应永恒的圣所，如今却变成一座倒悬于深渊的时空坟场：神庙立柱与齿轮机械的残骸漂浮在裂缝中，此处既是旧神陨落的墓志铭，亦是混沌吞噬信仰的屠宰场。"}
data[1150132] = { id = 1150132,  language = "风暴要塞"}
data[1150133] = { id = 1150133,  language = "混沌虫洞深处的风暴要塞栖息着强大的怪物，这些生物拥有着不可思议的能力：狂风暴雨交织化形，无端无影无踪，这里是它们的游乐场；逐日者被欲望驱使，将一切视为阻碍加以毁灭。"}
data[1150134] = { id = 1150134,  language = "永恒梦境"}
data[1150135] = { id = 1150135,  language = "永恒梦境由灭世歌姬的歌声编织而成。在梦里，人们探索世界本源，提升自身实力，突破原初之壁，抵御混沌入侵。然而，终究只是在梦里……"}
data[1150136] = { id = 1150136,  language = "残破的现实"}
data[1150137] = { id = 1150137,  language = "遗忘之穴"}
data[1150138] = { id = 1150138,  language = "阴暗潮湿的古老矿洞。充满矿车、铁镐、轨道等人造物品的痕迹，可以想象往日热火朝天的工作场景。"}
data[1150139] = { id = 1150139,  language = "巨石旷野"}
data[1150140] = { id = 1150140,  language = "一望无际的苍凉平原，奇怪的巨型岩石遍布。有人说这里是造物主诞生之地，那些岩石正是他们雕琢这个世界的证明。"}
