data[1251289] = { id = 1251289,  language = "你太弱了，我不相信你能够解决我的问题。等你完成时光之门最终试炼再来找我吧。"}
data[1251290] = { id = 1251290,  language = "强大的冒险者呀！快到我这里来！"}
data[1251291] = { id = 1251291,  language = "冒险者你好，我是绿洲商队的领袖阿加雷斯。"}
data[1251292] = { id = 1251292,  language = "我的商队在绝望之海沙漠中心的沙之眼，遭遇了可怕的危机"}
data[1251293] = { id = 1251293,  language = "听说巴萨坦的冒险者个个身经百战，我观察了这么多天"}
data[1251294] = { id = 1251294,  language = "我相信只有完成了时光之门最艰难挑战的你才能帮助我"}
data[1251295] = { id = 1251295,  language = "请你前往沙之眼，帮助我解决危机吧。"}
data[1251296] = { id = 1251296,  language = "嘿！小伙子，别急着了解我的秘密，先解决我的问题怎么样？"}
data[1251297] = { id = 1251297,  language = "这就是我喜欢凡人的原因，你们从来不会让我感到无聊。"}
data[1251298] = { id = 1251298,  language = "看来这些简单的挑战已经难不倒你们了，我得给你们准备一点……惊喜。"}
data[1251299] = { id = 1251299,  language = "现在，快离开这里吧，在你还没粉身碎骨之前。"}
data[1251300] = { id = 1251300,  language = "冒险者！你平安无事真是太好了！沙之眼发生了巨大的能量波动，连我们都感受到了。"}
data[1251301] = { id = 1251301,  language = "先去我的大篷车那领取奖励，然后再次前往沙之眼一探究竟吧！"}
